1	/*
2	 * AI模拟面试官 — 主程序入口
3	 * 负责：A/B同学
4	 *
5	 * 线程模型：
6	 *   主线程     按键扫描 + LED 刷新 + 排空事件队列（100ms 节拍）
7	 *   工作线程   录音 -> 上传 -> 播放 三段阻塞流水线
8	 *
9	 * 约束：state_machine 只由主线程调用。原因见 state_machine.c —— 它的
10	 * post_event / update_led 全程无锁（read-modify-write + GPIO ioctl + 闪烁
11	 * 计数器），多线程投递会丢状态、LED 交错，且是偶发问题最难复现。
12	 * 工作线程只往事件队列里放事件，不碰状态机、不碰 GPIO。
13	 *
14	 * 为什么必须分线程：单轮上传实测要 22 秒，若在主循环里做，LED 会僵住 22 秒
15	 * ——"系统还在工作"的唯一反馈就没了，按键也全部失灵。
16	 */
17	
18	#include <nuttx/config.h>
19	
20	#include <stdio.h>
21	#include <stdlib.h>
22	#include <string.h>
23	#include <unistd.h>
24	#include <fcntl.h>
25	#include <errno.h>
26	#include <pthread.h>
27	#include <sys/ioctl.h>
28	#include <nuttx/ioexpander/gpio.h>
29	
30	#include "state_machine.h"
31	#include "network_client.h"
32	#include "audio_io.h"
33	#include "app_config.h"
34	
35	/* ---- 按键 GPIO ---- */
36	#define KEY1_GPIO  1   /* K1 开始面试 */
37	#define KEY2_GPIO  3   /* K2 取消/返回 */
38	#define KEY3_GPIO  4   /* K3 切换模式（暂未实现）*/
39	
40	static int g_key1_fd = -1;
41	static int g_key2_fd = -1;
42	static int g_key3_fd = -1;
43	
44	static int g_key1_last = 1;  /* 默认高电平（松开）*/
45	static int g_key2_last = 1;
46	static int g_key3_last = 1;
47	
48	#define MAIN_LOOP_MS      100
49	#define UPLOAD_MAX_RETRY  3
50	#define UPLOAD_RETRY_SEC  3
51	
52	/* ---- 主线程 -> 工作线程 ---- */
53	typedef enum {
54	    CMD_NONE = 0,
55	    CMD_START,      /* K1：开始一轮面试 */
56	    CMD_CANCEL      /* K2：取消 */
57	} app_cmd_t;
58	
59	static pthread_mutex_t g_lock = PTHREAD_MUTEX_INITIALIZER;
60	static app_cmd_t g_cmd = CMD_NONE;
61	static volatile int g_abort = 0;     /* 置 1 让录音/播放尽快退出 */
62	static int g_worker_busy = 0;
63	
64	/* ---- 工作线程 -> 主线程 ---- */
65	#define EVQ_LEN 8
66	static system_event_t g_evq[EVQ_LEN];
67	static int g_evq_head = 0;
68	static int g_evq_tail = 0;
69	
70	/* 跨线程只读的会话状态（在锁内更新）*/
71	static char g_session_id[64];
72	static char g_last_text[256];
73	
74	/* ---------- 事件队列 ---------- */
75	
76	/* 工作线程调用 */
77	static void app_post_event(system_event_t e)
78	{
79	    int next;
80	
81	    pthread_mutex_lock(&g_lock);
82	    next = (g_evq_head + 1) % EVQ_LEN;
83	    if (next != g_evq_tail) {
84	        g_evq[g_evq_head] = e;
85	        g_evq_head = next;
86	    } else {
87	        printf("[Main] 警告: 事件队列已满，丢弃事件 %d\n", (int)e);
88	    }
89	    pthread_mutex_unlock(&g_lock);
90	}
91	
92	/* 主线程调用 */
93	static int app_pop_event(system_event_t *e)
94	{
95	    int got = 0;
96	
97	    pthread_mutex_lock(&g_lock);
98	    if (g_evq_tail != g_evq_head) {
99	        *e = g_evq[g_evq_tail];
100	        g_evq_tail = (g_evq_tail + 1) % EVQ_LEN;
101	        got = 1;
102	    }
103	    pthread_mutex_unlock(&g_lock);
104	
105	    return got;
106	}
107	
108	/* ---------- 流水线 ---------- */
109	
110	static int upload_once(const uint8_t *wav, size_t wav_len, cloud_response_t *resp)
111	{
112	    cloud_request_t req;
113	    char sid[64];
114	
115	    pthread_mutex_lock(&g_lock);
116	    strncpy(sid, g_session_id, sizeof(sid) - 1);
117	    sid[sizeof(sid) - 1] = '\0';
118	    pthread_mutex_unlock(&g_lock);
119	
120	    req.session_id = sid;
121	    req.wav = wav;
122	    req.wav_len = wav_len;
123	    req.role = app_role();
124	    req.state = "recording_finished";
125	
126	    return cloud_send_audio(&req, resp);
127	}
128	
129	static void run_one_round(void)
130	{
131	    uint8_t *wav = NULL;
132	    size_t wav_len = 0;
133	    cloud_response_t resp;
134	    ai_rec_result_t rec;
135	    int rc;
136	    int attempt;
137	
138	    memset(&resp, 0, sizeof(resp));
139	
140	    /* ---- 1. 录音 ---- */
141	    rec = audio_record_wav(&wav, &wav_len, &g_abort);
142	    if (rec != AI_REC_OK) {
143	        /* 三种失败都回到 IDLE：状态机里 RECORDING --ERROR--> IDLE */
144	        app_post_event(EVENT_ERROR);
145	        return;
146	    }
147	
148	    app_post_event(EVENT_RECORD_DONE);   /* RECORDING -> UPLOADING */
149	
150	    /* ---- 2. 上传（带重试）---- */
151	    rc = CLOUD_ERR_HTTP;
152	    for (attempt = 1; attempt <= UPLOAD_MAX_RETRY; attempt++) {
153	        rc = upload_once(wav, wav_len, &resp);
154	        if (rc == CLOUD_OK) {
155	            break;
156	        }
157	
158	        printf("[Main] 上传失败: %s（第 %d/%d 次）\n",
159	               cloud_strerror(rc), attempt, UPLOAD_MAX_RETRY);
160	
161	        if (rc == CLOUD_ERR_EMPTY_TTS) {
162	            break;      /* 云端缺 key 之类，重试没意义 */
163	        }
164	
165	        /* 间隔从 1 秒拉长到 3 秒：板子的 Wi-Fi 掉线后会重新做 WPA 握手，
166	         * 实测这个过程要几秒，1 秒的间隔等不到链路恢复，两次重试都会瞬间失败。
167	         * 最后一轮失败就没必要再等了。 */
168	        if (attempt < UPLOAD_MAX_RETRY) {
169	            sleep(UPLOAD_RETRY_SEC);
170	        }
171	    }
172	
173	    free(wav);
174	    wav = NULL;
175	
176	    if (rc != CLOUD_OK) {
177	        cloud_response_free(&resp);
178	        app_post_event(EVENT_UPLOAD_FAIL);   /* -> ERROR 或 IDLE */
179	        return;
180	    }
181	
182	    /* ---- 3. 记录会话状态，供下一轮回传 ---- */
183	    pthread_mutex_lock(&g_lock);
184	    if (resp.session_id[0] != '\0') {
185	        strncpy(g_session_id, resp.session_id, sizeof(g_session_id) - 1);
186	        g_session_id[sizeof(g_session_id) - 1] = '\0';
187	    }
188	    if (resp.text != NULL) {
189	        strncpy(g_last_text, resp.text, sizeof(g_last_text) - 1);
190	        g_last_text[sizeof(g_last_text) - 1] = '\0';
191	    }
192	    pthread_mutex_unlock(&g_lock);
193	
194	    /* ASR 原文单独打一行。之前只打面试官的回复，只能从回复里反推它有没有
195	     * 听对 —— 万一识别错了，看起来就像"模型答非所问"，会把排查方向带偏。 */
196	    printf("[Main] 我听到你说: %s\n",
197	           (resp.user_text != NULL && resp.user_text[0] != '\0')
198	               ? resp.user_text : "(空)");
199	    printf("[Main] 面试官: %s\n", resp.text ? resp.text : "(无文本)");
200	
201	    app_post_event(EVENT_UPLOAD_SUCCESS);    /* UPLOADING -> PLAYING */
202	
203	    /* ---- 4. 播放 ---- */
204	    (void)audio_play_wav(resp.tts_wav, resp.tts_wav_len, &g_abort);
205	
206	    /* 面试结束则清空会话，下次 K1 开新面试 */
207	    if (strcmp(resp.next_action, "continue") != 0) {
208	        printf("[Main] 本轮面试结束（next_action=%s）\n", resp.next_action);
209	        pthread_mutex_lock(&g_lock);
210	        g_session_id[0] = '\0';
211	        pthread_mutex_unlock(&g_lock);
212	    }
213	
214	    cloud_response_free(&resp);
215	
216	    /*
217	     * 必须是本函数最后一条语句。
218	     * 若在 free 之前投递，主线程会立刻转 IDLE，用户马上按 K1 开下一轮，
219	     * 而本线程还在收尾 —— 下一轮录音与上一轮释放并发。
220	     */
221	    app_post_event(EVENT_PLAY_DONE);         /* PLAYING -> IDLE */
222	}
223	
224	static void *pipeline_worker(void *arg)
225	{
226	    (void)arg;
227	
228	    /* libcurl 一律只在本线程里用：它需要 200KB 量级的栈
229	     * （参考 CONFIG_EXAMPLES_HTTP_STACKSIZE 默认 204800），主任务栈
230	     * 远不够。cloud_init 也放这里，避免主线程先初始化造成竞争。 */
231	    cloud_init();
232	
233	    printf("[Main] 云端健康检查...\n");
234	    if (cloud_health_check() != CLOUD_OK) {
235	        printf("[Main] 警告: 云端不可达，请检查 CLOUD_URL 与网络\n");
236	    }
237	
238	    for (;;) {
239	        app_cmd_t cmd;
240	
241	        pthread_mutex_lock(&g_lock);
242	        cmd = g_cmd;
243	        g_cmd = CMD_NONE;
244	        pthread_mutex_unlock(&g_lock);
245	
246	        if (cmd != CMD_START) {
247	            usleep(MAIN_LOOP_MS * 1000 / 2);
248	            continue;
249	        }
250	
251	        pthread_mutex_lock(&g_lock);
252	        g_worker_busy = 1;
253	        g_abort = 0;
254	        pthread_mutex_unlock(&g_lock);
255	
256	        run_one_round();
257	
258	        pthread_mutex_lock(&g_lock);
259	        g_worker_busy = 0;
260	        pthread_mutex_unlock(&g_lock);
261	    }
262	
263	    return NULL;
264	}
265	
266	/* ---------- 按键 ---------- */
267	
268	static int read_button(int fd)
269	{
270	    bool value = false;
271	
272	    if (fd < 0) {
273	        return -1;
274	    }
275	    ioctl(fd, GPIOC_READ, (unsigned long)((uintptr_t)&value));
276	    return value ? 1 : 0;
277	}
278	
279	/*
280	 * 取"上次状态"的初值。
281	 *
282	 * 不能直接假定为 1（松开）：这几个脚配的是下拉，K2/K3 悬空或未接时
283	 * 读到的是低电平，初值取 1 就会在开机第一次扫描时误判成一次"按下"。
284	 * 实测开机时 K2、K3 各误触发一次 —— K2 那次会把 g_abort 置 1；更要命的是
285	 * 万一它抢在 K1 前面，状态机会从 IDLE 直接进 RECORDING，而工作线程压根
286	 * 没收到 CMD_START，整机就卡在"录音中"了。
287	 *
288	 * fd 打不开时返回 1（维持原行为）：这种情形按键本来就用不了，
289	 * 循环里的 read_button() 会一直返回 -1，产生不了边沿。
290	 */
291	static int read_button_initial(int fd)
292	{
293	    int s = read_button(fd);
294	
295	    return (s < 0) ? 1 : s;
296	}
297	
298	static void init_buttons(void)
299	{
300	    g_key1_fd = open("/dev/gpio1", O_RDWR);
301	    if (g_key1_fd < 0) {
302	        printf("[Main] 警告: 无法打开 K1 GPIO (GPIO1)\n");
303	    } else {
304	        ioctl(g_key1_fd, GPIOC_SETPINTYPE, GPIO_INPUT_PIN_PULLDOWN);
305	        printf("[Main] K1 GPIO (GPIO1) 初始化成功\n");
306	    }
307	
308	    g_key2_fd = open("/dev/gpio3", O_RDWR);
309	    if (g_key2_fd < 0) {
310	        printf("[Main] 警告: 无法打开 K2 GPIO (GPIO3)\n");
311	    } else {
312	        ioctl(g_key2_fd, GPIOC_SETPINTYPE, GPIO_INPUT_PIN_PULLDOWN);
313	        printf("[Main] K2 GPIO (GPIO3) 初始化成功\n");
314	    }
315	
316	    g_key3_fd = open("/dev/gpio4", O_RDWR);
317	    if (g_key3_fd < 0) {
318	        printf("[Main] 警告: 无法打开 K3 GPIO (GPIO4)\n");
319	    } else {
320	        ioctl(g_key3_fd, GPIOC_SETPINTYPE, GPIO_INPUT_PIN_PULLDOWN);
321	        printf("[Main] K3 GPIO (GPIO4) 初始化成功\n");
322	    }
323	
324	    /* 初值取自实际电平，避免开机瞬间的假边沿 */
325	    g_key1_last = read_button_initial(g_key1_fd);
326	    g_key2_last = read_button_initial(g_key2_fd);
327	    g_key3_last = read_button_initial(g_key3_fd);
328	}
329	
330	static void check_buttons(void)
331	{
332	    int s1 = read_button(g_key1_fd);
333	    int s2 = read_button(g_key2_fd);
334	    int s3 = read_button(g_key3_fd);
335	    int busy;
336	
337	    pthread_mutex_lock(&g_lock);
338	    busy = g_worker_busy;
339	    pthread_mutex_unlock(&g_lock);
340	
341	    /* K1 下降沿：开始一轮。忙碌时忽略，避免重入 */
342	    if (s1 == 0 && g_key1_last == 1) {
343	        if (busy) {
344	            printf("[Main] K1 按下，但正在进行中，忽略\n");
345	        } else {
346	            printf("[Main] K1 按下 —— 开始面试\n");
347	            pthread_mutex_lock(&g_lock);
348	            g_cmd = CMD_START;
349	            pthread_mutex_unlock(&g_lock);
350	            state_machine_post_event(EVENT_BUTTON_PRESS);  /* -> RECORDING */
351	        }
352	    }
353	    g_key1_last = s1;
354	
355	    /* K2 下降沿：取消。置 abort，工作线程会在 100ms 粒度内退出 */
356	    if (s2 == 0 && g_key2_last == 1) {
357	        printf("[Main] K2 按下 —— 取消\n");
358	        g_abort = 1;
359	        /* 不忙碌时说明停在 ERROR 态，按一下回 IDLE。
360	         * 状态机调用放在锁外：持锁做 ioctl/printf 没有必要。 */
361	        if (!busy) {
362	            state_machine_post_event(EVENT_BUTTON_PRESS);
363	        }
364	    }
365	    g_key2_last = s2;
366	
367	    if (s3 == 0 && g_key3_last == 1) {
368	        printf("[Main] K3 按下（切换模式未实现）\n");
369	    }
370	    g_key3_last = s3;
371	}
372	
373	/* ---------- 入口 ---------- */
374	
375	int main(int argc, char *argv[])
376	{
377	    pthread_t tid;
378	    pthread_attr_t attr;
379	
380	    (void)argc;
381	    (void)argv;
382	
383	    printf("========================================\n");
384	    printf("  AI模拟面试官 - 端侧主程序 v0.2\n");
385	    printf("  队伍: mianbao (contest2026_151)\n");
386	    printf("========================================\n\n");
387	
388	    state_machine_init();
389	    init_buttons();
390	
391	    /* 流水线工作线程：栈必须够大，libcurl 要 200KB 量级。
392	     * 本函数内不得出现任何 curl 调用 —— 主任务栈放不下。 */
393	    pthread_attr_init(&attr);
394	    pthread_attr_setstacksize(&attr, CONFIG_APP_AI_INTERVIEW_WORKER_STACKSIZE);
395	    if (pthread_create(&tid, &attr, pipeline_worker, NULL) != 0) {
396	        printf("[Main] 致命错误: 工作线程创建失败 (%d)\n", errno);
397	        return 1;
398	    }
399	    pthread_attr_destroy(&attr);
400	
401	    printf("\n[Main] 系统就绪，等待按键开始面试...\n");
402	    printf("[Main] K1: 开始面试\n");
403	    printf("[Main] K2: 取消/返回\n");
404	    printf("[Main] K3: 切换模式\n\n");
405	
406	    for (;;) {
407	        system_event_t ev;
408	
409	        state_machine_update_led();
410	        check_buttons();
411	
412	        /* 把工作线程投来的事件交给状态机 —— 只有主线程能碰它 */
413	        while (app_pop_event(&ev)) {
414	            state_machine_post_event(ev);
415	        }
416	
417	        usleep(MAIN_LOOP_MS * 1000);
418	    }
419	
420	    return 0;
421	}
