1	/*
2	 * AI模拟面试官 — 网络通信模块
3	 * 负责：A同学
4	 *
5	 * 端侧 -> 云端：POST /api/interview，body 为 JSON，音频以 base64 内嵌
6	 * 云端 -> 端侧：JSON，tts_audio 为 base64 编码的 WAV
7	 *
8	 * 依赖（R528 板级配置已具备，无需改 defconfig）：
9	 *   CONFIG_LIB_CURL            HTTP 客户端（连带 CRYPTO_MBEDTLS / LIB_ZLIB）
10	 *   CONFIG_NETUTILS_CJSON      JSON 解析
11	 *   mbedtls/base64.h           base64 编解码（由 CONFIG_LIB_CURL 间接引入）
12	 *
13	 * 注意：libcurl 需要 200KB 量级的栈（参考 CONFIG_EXAMPLES_HTTP_STACKSIZE=204800）。
14	 * 本应用主任务栈已提到 32768，网络调用务必在工作线程（栈 262144）里执行。
15	 */
16	
17	#include <stdio.h>
18	#include <stdlib.h>
19	#include <string.h>
20	
21	#include <curl/curl.h>
22	#include "netutils/cJSON.h"
23	#include <mbedtls/base64.h>
24	
25	#include "network_client.h"
26	#include "app_config.h"
27	
28	/* 单次响应上限：24kHz 单声道 WAV 的 base64 约 10 秒 640KB，留足余量 */
29	#define CLOUD_RESP_MAX  (8u * 1024u * 1024u)
30	
31	/* 请求路径：只配 base URL，路径写死在这里避免两处配置漂移 */
32	#define CLOUD_PATH_INTERVIEW  "/api/interview"
33	#define CLOUD_PATH_HEALTH     "/api/health"
34	
35	static char g_url_interview[192];
36	static char g_url_health[192];
37	static int  g_initialized = 0;
38	
39	const char *cloud_strerror(int rc)
40	{
41	    switch (rc) {
42	        case CLOUD_OK:              return "成功";
43	        case CLOUD_ERR_HTTP:        return "HTTP 传输失败或非 2xx（多半是网络不通）";
44	        case CLOUD_ERR_JSON:        return "响应不是合法 JSON 或结构不符协议";
45	        case CLOUD_ERR_EMPTY_TTS:   return "tts_audio 为空（云端多半缺 API key）";
46	        case CLOUD_ERR_BAD_AUDIO:   return "解码后不是可播放的 WAV";
47	        case CLOUD_ERR_NOMEM:       return "内存不足";
48	        default:                    return "未知错误";
49	    }
50	}
51	
52	/* ---------- 响应缓冲 ---------- */
53	
54	struct mem_chunk {
55	    char  *memory;
56	    size_t size;
57	};
58	
59	static size_t write_memory_cb(void *contents, size_t size, size_t nmemb,
60	                              void *userp)
61	{
62	    size_t realsize = size * nmemb;
63	    struct mem_chunk *mem = (struct mem_chunk *)userp;
64	    char *ptr;
65	
66	    /* 超限返回 0 让 curl 以 CURLE_WRITE_ERROR 中止，而不是把内存吃光 */
67	    if (mem->size + realsize > CLOUD_RESP_MAX) {
68	        printf("[Cloud] 响应超过上限 %u 字节，中止\n", (unsigned)CLOUD_RESP_MAX);
69	        return 0;
70	    }
71	
72	    ptr = realloc(mem->memory, mem->size + realsize + 1);
73	    if (ptr == NULL) {
74	        printf("[Cloud] 响应缓冲分配失败\n");
75	        return 0;
76	    }
77	
78	    mem->memory = ptr;
79	    memcpy(&(mem->memory[mem->size]), contents, realsize);
80	    mem->size += realsize;
81	    mem->memory[mem->size] = '\0';
82	
83	    return realsize;
84	}
85	
86	/* ---------- 初始化 ---------- */
87	
88	void cloud_init(void)
89	{
90	    const char *base;
91	
92	    if (g_initialized) {
93	        return;
94	    }
95	
96	    curl_global_init(CURL_GLOBAL_ALL);
97	
98	    base = app_cloud_base_url();
99	    snprintf(g_url_interview, sizeof(g_url_interview), "%s%s",
100	             base, CLOUD_PATH_INTERVIEW);
101	    snprintf(g_url_health, sizeof(g_url_health), "%s%s",
102	             base, CLOUD_PATH_HEALTH);
103	
104	    printf("[Cloud] 云端接口: %s\n", g_url_interview);
105	
106	    g_initialized = 1;
107	}
