109	/* ---------- 健康检查 ---------- */
110	
111	int cloud_health_check(void)
112	{
113	    CURL *curl;
114	    CURLcode res;
115	    struct mem_chunk chunk;
116	    long status = 0;
117	    int ret = CLOUD_ERR_HTTP;
118	
119	    cloud_init();
120	
121	    chunk.memory = malloc(1);
122	    if (chunk.memory == NULL) {
123	        return CLOUD_ERR_NOMEM;
124	    }
125	    chunk.size = 0;
126	
127	    curl = curl_easy_init();
128	    if (curl == NULL) {
129	        free(chunk.memory);
130	        return CLOUD_ERR_HTTP;
131	    }
132	
133	    curl_easy_setopt(curl, CURLOPT_URL, g_url_health);
134	    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_memory_cb);
135	    curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);
136	    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);
137	    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 15L);
138	    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);
139	
140	    res = curl_easy_perform(curl);
141	    if (res == CURLE_OK) {
142	        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &status);
143	        if (status >= 200 && status < 300) {
144	            ret = CLOUD_OK;
145	        }
146	    } else {
147	        printf("[Cloud] 健康检查失败: %s\n", curl_easy_strerror(res));
148	    }
149	
150	    curl_easy_cleanup(curl);
151	    free(chunk.memory);
152	
153	    printf("[Cloud] 健康检查 HTTP %ld -> %s\n", status,
154	           ret == CLOUD_OK ? "云端在线" : "云端不可达");
155	    return ret;
156	}
157	
158	/* ---------- 响应解析 ---------- */
159	
160	/* 从 JSON 里取字符串字段并复制一份堆内存；字段缺失返回 NULL（不算错误） */
161	static char *dup_string_field(const cJSON *root, const char *name)
162	{
163	    const cJSON *item = cJSON_GetObjectItem(root, name);
164	    size_t len;
165	    char *out;
166	
167	    if (!cJSON_IsString(item) || item->valuestring == NULL) {
168	        return NULL;
169	    }
170	
171	    len = strlen(item->valuestring);
172	    out = malloc(len + 1);
173	    if (out == NULL) {
174	        return NULL;
175	    }
176	
177	    memcpy(out, item->valuestring, len + 1);
178	    return out;
179	}
180	
181	/*
182	 * 失败时统一从这里返回：释放已分配字段并把 resp 归零，
183	 * 保证调用者无论成败都可以安全地调 cloud_response_free()，
184	 * 也保证错误路径不会留下半成品结构体。
185	 */
186	static int parse_fail(cloud_response_t *resp, int err)
187	{
188	    free(resp->text);
189	    free(resp->user_text);
190	    free(resp->tts_wav);
191	    memset(resp, 0, sizeof(*resp));
192	    return err;
193	}
194	
195	int cloud_parse_response(const char *body, size_t len, cloud_response_t *resp)
196	{
197	    cJSON *root;
198	    const cJSON *item;
199	    size_t b64_len;
200	    size_t wav_len = 0;
201	    unsigned char *wav;
202	    int rc;
203	
204	    if (body == NULL || resp == NULL || len == 0) {
205	        return CLOUD_ERR_JSON;
206	    }
207	
208	    root = cJSON_ParseWithLength(body, len);
209	    if (root == NULL) {
210	        printf("[Cloud] 响应不是合法 JSON\n");
211	        return CLOUD_ERR_JSON;
212	    }
213	
214	    /* session_id / next_action 是定长字段，直接拷进结构体 */
215	    item = cJSON_GetObjectItem(root, "session_id");
216	    if (cJSON_IsString(item) && item->valuestring != NULL) {
217	        strncpy(resp->session_id, item->valuestring,
218	                sizeof(resp->session_id) - 1);
219	        resp->session_id[sizeof(resp->session_id) - 1] = '\0';
220	    }
221	
222	    item = cJSON_GetObjectItem(root, "next_action");
223	    if (cJSON_IsString(item) && item->valuestring != NULL) {
224	        strncpy(resp->next_action, item->valuestring,
225	                sizeof(resp->next_action) - 1);
226	        resp->next_action[sizeof(resp->next_action) - 1] = '\0';
227	    }
228	
229	    resp->text = dup_string_field(root, "text");
230	    resp->user_text = dup_string_field(root, "user_text");
231	
232	    /*
233	     * 防线 2：tts_audio 必须存在、是字符串、且非空。
234	     *
235	     * 云端在缺 MIMO_API_KEY 时会返回 HTTP 200 但 tts_audio 为空串，
236	     * 若这里放过，端侧会一路"成功"到播放环节却没有声音——演示时最难查。
237	     */
238	    item = cJSON_GetObjectItem(root, "tts_audio");
239	    if (!cJSON_IsString(item) || item->valuestring == NULL ||
240	        item->valuestring[0] == '\0') {
241	        /* text 里通常有云端给的兜底文案，打到串口便于定位 */
242	        printf("[Cloud] 响应缺少 tts_audio（云端可能未配置 API key）: %s\n",
243	               resp->text ? resp->text : "(无 text)");
244	        cJSON_Delete(root);
245	        return parse_fail(resp, CLOUD_ERR_EMPTY_TTS);
246	    }
247	
248	    b64_len = strlen(item->valuestring);
249	
250	    /* 先探解码后长度，再分配：mbedtls 在缓冲不足时回填所需大小 */
251	    rc = mbedtls_base64_decode(NULL, 0, &wav_len,
252	                               (const unsigned char *)item->valuestring, b64_len);
253	    if (rc != 0 && rc != MBEDTLS_ERR_BASE64_BUFFER_TOO_SMALL) {
254	        printf("[Cloud] tts_audio 不是合法 base64\n");
255	        cJSON_Delete(root);
256	        return parse_fail(resp, CLOUD_ERR_BAD_AUDIO);
257	    }
258	
259	    if (wav_len < 60) {  /* 44 字节头 + 至少一点数据 */
260	        cJSON_Delete(root);
261	        return parse_fail(resp, CLOUD_ERR_BAD_AUDIO);
262	    }
263	
264	    wav = malloc(wav_len);
265	    if (wav == NULL) {
266	        cJSON_Delete(root);
267	        return parse_fail(resp, CLOUD_ERR_NOMEM);
268	    }
269	
270	    rc = mbedtls_base64_decode(wav, wav_len, &wav_len,
271	                               (const unsigned char *)item->valuestring, b64_len);
272	    cJSON_Delete(root);  /* 后续不再需要 JSON 树，尽早释放 */
273	
274	    if (rc != 0) {
275	        free(wav);
276	        return parse_fail(resp, CLOUD_ERR_BAD_AUDIO);
277	    }
278	
279	    /*
280	     * 防线 3：解码后必须是 WAV。
281	     * 云端异常时 tts_audio 里可能是错误文本或 HTML，直接送播放器会放出噪声。
282	     */
283	    if (wav_len < 44 || memcmp(wav, "RIFF", 4) != 0 ||
284	        memcmp(wav + 8, "WAVE", 4) != 0) {
285	        printf("[Cloud] tts_audio 解码后不是 WAV\n");
286	        free(wav);
287	        return parse_fail(resp, CLOUD_ERR_BAD_AUDIO);
288	    }
289	
290	    resp->tts_wav = wav;
291	    resp->tts_wav_len = wav_len;
292	
293	    return CLOUD_OK;
294	}
295	
296	/* ---------- 主请求 ---------- */
297	
298	int cloud_send_audio(const cloud_request_t *req, cloud_response_t *resp)
299	{
300	    CURL *curl = NULL;
301	    struct curl_slist *headers = NULL;
302	    struct mem_chunk chunk;
303	    CURLcode res;
304	    long status = 0;
305	    char *b64 = NULL;
306	    char *body = NULL;
307	    size_t b64_cap;
308	    size_t b64_len = 0;
309	    size_t body_cap;
310	    const char *sid;
311	    int ret;
312	
313	    if (req == NULL || resp == NULL || req->wav == NULL || req->wav_len == 0) {
314	        return CLOUD_ERR_JSON;
315	    }
316	
317	    cloud_init();
318	
319	    memset(resp, 0, sizeof(*resp));
320	    chunk.memory = malloc(1);
321	    if (chunk.memory == NULL) {
322	        return CLOUD_ERR_NOMEM;
323	    }
324	    chunk.size = 0;
325	
326	    /*
327	     * base64 编码。mbedtls 会在末尾写 '\0'，所以容量要 +1。
328	     * 用 mbedtls 而不是 apps/netutils/codecs：后者需要 CONFIG_CODECS_BASE64，
329	     * 而该配置在板级 defconfig 里没开，且 defconfig 不在本仓库内。
330	     */
331	    b64_cap = 4 * ((req->wav_len + 2) / 3) + 1;
332	    b64 = malloc(b64_cap);
333	    if (b64 == NULL) {
334	        ret = CLOUD_ERR_NOMEM;
335	        goto out;
336	    }
337	
338	    if (mbedtls_base64_encode((unsigned char *)b64, b64_cap, &b64_len,
339	                              req->wav, req->wav_len) != 0) {
340	        printf("[Cloud] 音频 base64 编码失败\n");
341	        ret = CLOUD_ERR_NOMEM;
342	        goto out;
343	    }
344	
345	    /*
346	     * 手写拼 JSON，不用 cJSON_Print：后者会把 1MB 级的 base64 串再复制转义
347	     * 一遍，峰值内存翻倍。
348	     * 无需转义——session_id 是 uuid、role 是固定常量、base64 只含 A-Za-z0-9+/=。
349	     * history 恒为空数组：多轮上下文由云端按 session_id 维护。
350	     */
351	    sid = (req->session_id != NULL) ? req->session_id : "";
352	    body_cap = b64_len + strlen(sid) + strlen(req->role) +
353	               strlen(req->state) + 256;
354	    body = malloc(body_cap);
355	    if (body == NULL) {
356	        ret = CLOUD_ERR_NOMEM;
357	        goto out;
358	    }
359	
360	    snprintf(body, body_cap,
361	             "{\"session_id\":\"%s\",\"audio\":\"%s\",\"audio_format\":\"wav\","
362	             "\"role\":\"%s\",\"state\":\"%s\",\"history\":[]}",
363	             sid, b64, req->role, req->state);
364	
365	    /* body 已拼好，立刻释放 base64 缓冲，降低峰值内存 */
366	    free(b64);
367	    b64 = NULL;
368	
369	    curl = curl_easy_init();
370	    if (curl == NULL) {
371	        ret = CLOUD_ERR_HTTP;
372	        goto out;
373	    }
374	
375	    /*
376	     * 两个头缺一不可：
377	     *   Content-Type  缺了 Flask 的 request.get_json() 返回 None，云端直接回
378	     *                 400「请求体不能为空」，很容易误判成音频格式问题
379	     *   Expect:       抑制 100-continue，否则 body 超过 1KB 时 curl 会先发
380	     *                 Expect 头等待应答，白等 1 秒甚至失败
381	     */
382	    headers = curl_slist_append(headers, "Content-Type: application/json");
383	    headers = curl_slist_append(headers, "Expect:");
384	
385	    curl_easy_setopt(curl, CURLOPT_URL, g_url_interview);
386	    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
387	    curl_easy_setopt(curl, CURLOPT_POST, 1L);
388	    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, body);
389	    curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(body));
390	    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_memory_cb);
391	    curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);
392	    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 10L);
393	    /* 云端要串行跑 ASR + LLM + TTS，实测可能十几秒，给足余量 */
394	    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 120L);
395	    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);
396	    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
397	
398	    /*
399	     * TLS 证书校验默认是打开的（libcurl 默认行为）。
400	     *
401	     * 注意：板级 rootfs 里没有任何 CA 根证书
402	     * （CONFIG_LIB_CURL_CA_PATH 默认 /etc/ssl/curl，该路径不存在），
403	     * 因此走 https:// 时校验必然失败。
404	     *
405	     * 两条出路 —— 优先前者：
406	     *   1. 在设备上放一份 CA bundle，并把 CURLOPT_CAINFO 指过去
407	     *   2. 显式打开 APP_AI_INTERVIEW_TLS_INSECURE 跳过校验
408	     *      （仅适用于连自己的服务，演示用；不要长期开着）
409	     *
410	     * 用 http:// 时这里完全没有影响。
411	     */
412	#if defined(CONFIG_APP_AI_INTERVIEW_TLS_INSECURE)
413	    printf("[Cloud] 警告: 已跳过 TLS 证书校验\n");
414	    curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 0L);
415	    curl_easy_setopt(curl, CURLOPT_SSL_VERIFYHOST, 0L);
416	#endif
417	
418	    res = curl_easy_perform(curl);
419	    if (res != CURLE_OK) {
420	        printf("[Cloud] 上传失败: %s\n", curl_easy_strerror(res));
421	        resp->http_status = 0;
422	        ret = CLOUD_ERR_HTTP;
423	        goto out;
424	    }
425	
426	    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &status);
427	    resp->http_status = status;
428	
429	    /* 防线 1：HTTP 状态码 */
430	    if (status < 200 || status >= 300) {
431	        printf("[Cloud] 云端返回 HTTP %ld\n", status);
432	        ret = CLOUD_ERR_HTTP;
433	        goto out;
434	    }
435	
436	    /* 防线 2、3 都在 cloud_parse_response 内，保持判定逻辑单点 */
437	    ret = cloud_parse_response(chunk.memory, chunk.size, resp);
438	    resp->http_status = status;
439	
440	    if (ret == CLOUD_OK) {
441	        printf("[Cloud] 本轮成功: %u 字节 WAV, next_action=%s\n",
442	               (unsigned)resp->tts_wav_len,
443	               resp->next_action[0] ? resp->next_action : "?");
444	    }
445	
446	out:
447	    if (headers != NULL) {
448	        curl_slist_free_all(headers);
449	    }
450	    if (curl != NULL) {
451	        curl_easy_cleanup(curl);
452	    }
453	    free(b64);
454	    free(body);
455	    free(chunk.memory);
456	    return ret;
457	}
458	
459	/* ---------- 清理 ---------- */
460	
461	void cloud_response_free(cloud_response_t *resp)
462	{
463	    if (resp == NULL) {
464	        return;
465	    }
466	
467	    free(resp->text);
468	    free(resp->user_text);
469	    free(resp->tts_wav);
470	
471	    memset(resp, 0, sizeof(*resp));
472	}
