149	/* LED 闪烁控制变量 */
150	static int g_led_blink_state = 0;  /* 闪烁状态: 0=灭, 1=亮 */
151	static int g_led_blink_count = 0;  /* 闪烁计数 */
152	static int g_led_blink_pattern = 0; /* 闪烁模式: 0=快闪, 1=慢闪, 2=三短闪 */
153	
154	void state_machine_update_led(void)
155	{
156	    switch (g_current_state) {
157	        case STATE_IDLE:
158	            /* 待机: LED1 常亮 */
159	            if (g_led1_fd >= 0) {
160	                ioctl(g_led1_fd, GPIOC_WRITE, 0);  /* LED1 亮 */
161	            }
162	            break;
163	
164	        case STATE_RECORDING:
165	            /* 录音中: LED1 快闪 (200ms间隔) */
166	            if (g_led1_fd >= 0) {
167	                g_led_blink_state = !g_led_blink_state;
168	                ioctl(g_led1_fd, GPIOC_WRITE, g_led_blink_state ? 1 : 0);
169	            }
170	            break;
171	
172	        case STATE_UPLOADING:
173	            /* 上传中: LED1 慢闪 (800ms间隔) */
174	            if (g_led1_fd >= 0) {
175	                g_led_blink_state = !g_led_blink_state;
176	                ioctl(g_led1_fd, GPIOC_WRITE, g_led_blink_state ? 1 : 0);
177	            }
178	            break;
179	
180	        case STATE_PLAYING:
181	            /* 播放中: LED2 常亮 */
182	            if (g_led2_fd >= 0) {
183	                ioctl(g_led2_fd, GPIOC_WRITE, 0);  /* LED2 亮 */
184	            }
185	            break;
186	
187	        case STATE_ERROR:
188	            /* 错误: LED1 三短闪循环 */
189	            if (g_led1_fd >= 0) {
190	                g_led_blink_count++;
191	                if (g_led_blink_count <= 6) {  /* 3次闪烁 = 6次状态切换 */
192	                    g_led_blink_state = !g_led_blink_state;
193	                    ioctl(g_led1_fd, GPIOC_WRITE, g_led_blink_state ? 1 : 0);
194	                } else if (g_led_blink_count <= 12) {  /* 停顿 */
195	                    ioctl(g_led1_fd, GPIOC_WRITE, 1);  /* LED1 灭 */
196	                } else {
197	                    g_led_blink_count = 0;  /* 重新开始 */
198	                }
199	            }
200	            break;
201	    }
202	}
