204	void led_set(led_color_t color, led_mode_t mode)
205	{
206	    printf("[LED] 颜色=%d, 模式=%d\n", color, mode);
207	
208	    /* 根据颜色选择 GPIO */
209	    int fd = -1;
210	    if (color == LED_GREEN || color == LED_RED) {
211	        fd = g_led1_fd;  /* LED1 用于绿色/红色指示 */
212	    } else if (color == LED_BLUE) {
213	        fd = g_led2_fd;  /* LED2 用于蓝色指示 */
214	    }
215	
216	    if (fd < 0) {
217	        printf("[LED] 错误: GPIO 未初始化\n");
218	        return;
219	    }
220	
221	    /* 根据模式控制 LED */
222	    switch (mode) {
223	        case LED_MODE_ON:
224	            /* 常亮 - 低电平有效 */
225	            ioctl(fd, GPIOC_WRITE, 0);
226	            break;
227	        case LED_MODE_OFF:
228	            /* 熄灭 - 高电平有效 */
229	            ioctl(fd, GPIOC_WRITE, 1);
230	            break;
231	        case LED_MODE_BLINK:
232	            /* 闪烁 - 快闪 (200ms间隔) */
233	            printf("[LED] 闪烁模式需要在主循环中实现\n");
234	            break;
235	        case LED_MODE_BREATH:
236	            /* 呼吸灯 - 慢闪 (800ms间隔) */
237	            printf("[LED] 呼吸灯模式需要在主循环中实现\n");
238	            break;
239	        default:
240	            break;
241	    }
242	}
