33	/*
34	 * 配置 codec。
35	 *
36	 * 两件事都必须做，缺一不可：
37	 *
38	 * 1) 打开模拟输入通路。codec 默认不启用任何 ADC 输入路由，而
39	 *    sunxi_codec_hw_params() 会在 sunxi_get_adc_ch() 返回负值时直接失败，
40	 *    并打出一条误导性的 "capture only support 1~3 channel" —— 它检查的
41	 *    其实不是请求的通道数，而是"模拟输入通路有没有被打开"。
42	 *
43	 * 2) 设置 ADC/DAC 音量。ADC 数字音量若为默认低值，采到的 PCM 会被压成
44	 *    接近全零（实测表现为持续 RMS≈1，说话也毫无反应）。这一点最初漏掉了，
45	 *    上板后才发现。
46	 *
47	 * 录制通道数跟着打开的输入通路走：只开 MIC1 就得到单声道，与本模块请求的
48	 * 1 声道一致（codec 按 adc1/adc2/adc3_flag 逐个使能 ADC 数字通道）。
49	 *
50	 * 取值来自队伍此前在这块板子上验证过的 amixer 配方
51	 * （amixer set 19/20/21 255、6/7 150、15 7），此处改用控件名以免索引漂移。
52	 */
53	static int codec_configure(void)
54	{
55	    static const struct {
56	        const char  *name;
57	        unsigned int value;
58	    } settings[] = {
59	        /* 采集：输入通路 + 数字音量 */
60	        { "MIC1 input switch",   1   },
61	        { "MIC1 gain volume",    19  },
62	        { "ADC1 digital volume", 255 },
63	        { "ADC2 digital volume", 255 },
64	        { "ADC3 digital volume", 255 },
65	        /* 播放：数字音量 + 耳机增益 */
66	        { "DACL digital volume", 150 },
67	        { "DACR digital volume", 150 },
68	        { "HPOUT gain volume",   7   },
69	    };
70	    size_t i;
71	    int failed = 0;
72	
73	    for (i = 0; i < sizeof(settings) / sizeof(settings[0]); i++) {
74	        if (snd_ctl_set(AI_CODEC_CARD, settings[i].name,
75	                        settings[i].value) < 0) {
76	            printf("[Audio] 设置 %s 失败\n", settings[i].name);
77	            failed++;
78	        }
79	    }
80	
81	    if (failed != 0) {
82	        printf("[Audio] codec 配置有 %d 项失败，录音可能无声\n", failed);
83	        return -1;
84	    }
85	
86	    printf("[Audio] codec 已配置（输入通路 + ADC/DAC 音量）\n");
87	    return 0;
88	}
