90	/* 录音参数：16kHz 单声道 16bit —— ASR 的通用首选，也是云端 demo 用的配置 */
91	#define AI_REC_RATE     16000u
92	#define AI_REC_CHANNELS 1u
93	#define AI_REC_BITS     16u
94	
95	/* 分块与判定节奏，均以 100ms 为粒度（与主循环节拍一致）*/
96	#define AI_CHUNK_MS            100u
97	#define AI_SILENCE_CHUNKS      20   /* 连续 2 秒静音 -> 认为说完了 */
98	#define AI_MIN_SPEECH_CHUNKS    3   /* 至少 300ms 人声才允许被静音截断 */
99	#define AI_NOSPEECH_CHUNKS     50   /* 5 秒还没出声 -> 判定没人说话 */
100	#define AI_LONG_SILENCE_CHUNKS 40   /* 4 秒：出过声但人声没攒够时的强制收尾 */
101	
102	static void put_le32(uint8_t *p, uint32_t v)
103	{
104	    p[0] = (uint8_t)(v);
105	    p[1] = (uint8_t)(v >> 8);
106	    p[2] = (uint8_t)(v >> 16);
107	    p[3] = (uint8_t)(v >> 24);
108	}
109	
110	static void put_le16(uint8_t *p, uint16_t v)
111	{
112	    p[0] = (uint8_t)(v);
113	    p[1] = (uint8_t)(v >> 8);
114	}
115	
116	static uint32_t get_le32(const uint8_t *p)
117	{
118	    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
119	           ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
120	}
121	
122	static uint16_t get_le16(const uint8_t *p)
123	{
124	    return (uint16_t)(p[0] | (p[1] << 8));
125	}
126	
127	/*
128	 * 整数平方根（牛顿迭代）。
129	 *
130	 * 只用来把均方换算成与静音门限同量纲的 RMS，好让日志里的数值能直接跟
131	 * 门限对照 —— 否则打出来的是均方，门限是 RMS，两者差一个平方，现场
132	 * 调参时极易误判。
133	 *
134	 * 自己实现而不是调 sqrt()：避免为这一个函数引入 libm 依赖。
135	 */
136	static unsigned int isqrt_u32(uint32_t v)
137	{
138	    uint32_t x;
139	    uint32_t y;
140	
141	    if (v == 0) {
142	        return 0;
143	    }
144	
145	    x = v;
146	    y = (x + 1) / 2;
147	    while (y < x) {
148	        x = y;
149	        y = (x + v / x) / 2;
150	    }
151	
152	    return (unsigned int)x;
153	}
154	
155	/* 写 44 字节标准 PCM WAV 头 */
156	static void wav_write_header(uint8_t *h, uint32_t data_size,
157	                             unsigned channels, unsigned rate, unsigned bits)
158	{
159	    uint16_t block_align = (uint16_t)(channels * (bits / 8));
160	
161	    memcpy(h, "RIFF", 4);
162	    put_le32(h + 4, 36 + data_size);
163	    memcpy(h + 8, "WAVE", 4);
164	    memcpy(h + 12, "fmt ", 4);
165	    put_le32(h + 16, 16);            /* fmt 块长度 */
166	    put_le16(h + 20, 1);             /* 1 = PCM */
167	    put_le16(h + 22, (uint16_t)channels);
168	    put_le32(h + 24, rate);
169	    put_le32(h + 28, rate * block_align);   /* 字节率 */
170	    put_le16(h + 32, block_align);
171	    put_le16(h + 34, (uint16_t)bits);
172	    memcpy(h + 36, "data", 4);
173	    put_le32(h + 40, data_size);
174	}
175	
176	/*
177	 * 解析 WAV 头。只支持标准 44 字节布局（fmt 后紧跟 data）—— 云端 TTS 返回的
178	 * 就是这种（实测 399404 = 44 + 399360）。带附加块的 WAV 会被判为不支持，
179	 * 宁可报错也不要放出一段噪声。
180	 */
181	static int wav_parse(const uint8_t *w, size_t len, unsigned *rate,
182	                     unsigned *channels, unsigned *bits,
183	                     size_t *data_off, size_t *data_len)
184	{
185	    uint32_t dlen;
186	
187	    if (w == NULL || len < 44) {
188	        return -1;
189	    }
190	    if (memcmp(w, "RIFF", 4) != 0 || memcmp(w + 8, "WAVE", 4) != 0) {
191	        return -1;
192	    }
193	    if (memcmp(w + 12, "fmt ", 4) != 0 || get_le16(w + 20) != 1) {
194	        return -1;
195	    }
196	    if (memcmp(w + 36, "data", 4) != 0) {
197	        return -1;
198	    }
199	
200	    *channels = get_le16(w + 22);
201	    *rate = get_le32(w + 24);
202	    *bits = get_le16(w + 34);
203	    dlen = get_le32(w + 40);
204	
205	    if (*channels < 1 || *channels > 2 || *bits != 16 ||
206	        *rate < 8000 || *rate > 96000) {
207	        return -1;
208	    }
209	
210	    *data_off = 44;
211	    /* 头部声明比实际文件长时不硬信声明值 */
212	    *data_len = (dlen <= len - 44) ? dlen : (len - 44);
213	    return (*data_len > 0) ? 0 : -1;
214	}
