237	ai_rec_result_t audio_record_wav(uint8_t **out, size_t *out_len,
238	                                 volatile int *abort)
239	{
240	    snd_pcm_t *handle = NULL;
241	    uint8_t *buf;
242	    int16_t *scratch = NULL;
243	    size_t cap;
244	    size_t pcm_len = 0;
245	    const unsigned int in_ch = app_capture_channels();
246	    const unsigned int in_frame_bytes = in_ch * (AI_REC_BITS / 8);
247	    const unsigned int out_frame_bytes = AI_REC_CHANNELS * (AI_REC_BITS / 8);
248	    const unsigned int gain = app_mic_gain();
249	    const unsigned int thr = app_silence_threshold();
250	    const unsigned int max_sec = app_max_record_seconds();
251	    const unsigned chunk_frames = AI_REC_RATE / (1000 / AI_CHUNK_MS);
252	    int silence_run = 0;
253	    int speech_chunks = 0;
254	    int chunks = 0;
255	    ai_rec_result_t result = AI_REC_OK;
256	    int rc;
257	
258	    /* 每秒统计用。整秒 RMS 要累计这一秒**所有采样点**的平方和，
259	     * 单块极值则用来定门限：要看的是"说话时最低掉到多少、安静时最高
260	     * 冒到多少"，平均值会把两头的边界抹平，看不到余量。 */
261	    long long sec_sum2 = 0;
262	    long long sec_n = 0;
263	    unsigned int sec_min = 0;   /* 用 unsigned int 而非 uint32_t：本目标上
264	                                 * uint32_t 是 unsigned long，与 %u 不匹配 */
265	    unsigned int sec_max = 0;
266	    int sec_chunks = 0;
267	    int sec_speech = 0;
268	    int sec_no = 0;
269	
270	    if (out == NULL || out_len == NULL) {
271	        return AI_REC_ERROR;
272	    }
273	
274	    /* 录音缓冲按**单声道**尺寸分配：采集到的多声道会下混后再写入 */
275	    cap = (size_t)max_sec * AI_REC_RATE * out_frame_bytes;
276	    buf = malloc(44 + cap);
277	    if (buf == NULL) {
278	        printf("[Audio] 录音缓冲分配失败 (%u 字节)\n", (unsigned)(44 + cap));
279	        return AI_REC_ERROR;
280	    }
281	
282	    scratch = malloc((size_t)chunk_frames * in_frame_bytes);
283	    if (scratch == NULL) {
284	        printf("[Audio] 暂存缓冲分配失败\n");
285	        free(buf);
286	        return AI_REC_ERROR;
287	    }
288	
289	    /* 必须先配好 codec（输入通路 + ADC 音量），否则要么 hw_params 失败，
290	     * 要么采回一堆全零 */
291	    if (codec_configure() < 0) {
292	        free(buf);
293	        return AI_REC_ERROR;
294	    }
295	
296	    printf("[Audio] 采集设备: %s, %u 声道, 数字增益 x%u\n",
297	           app_capture_device(), in_ch, gain);
298	
299	    rc = snd_vela_pcm_open(&handle, app_capture_device(),
300	                           SND_VELA_PCM_STREAM_CAPTURE, 0);
301	    if (rc < 0) {
302	        printf("[Audio] 打开录音设备失败: %d\n", rc);
303	        free(scratch);
304	        free(buf);
305	        return AI_REC_ERROR;
306	    }
307	
308	    rc = set_param(handle, SND_PCM_FORMAT_S16_LE, AI_REC_RATE,
309	                   in_ch, 1024, 4096);
310	    if (rc < 0) {
311	        printf("[Audio] 录音参数配置失败: %d\n", rc);
312	        snd_vela_pcm_close(handle);
313	        free(scratch);
314	        free(buf);
315	        return AI_REC_ERROR;
316	    }
317	
318	    printf("[Audio] 开始录音（静音 %.1f 秒自动结束，最长 %u 秒，门限 RMS %u）\n",
319	           (double)AI_SILENCE_CHUNKS * AI_CHUNK_MS / 1000.0, max_sec, thr);
320	
321	    for (;;) {
322	        const int16_t *src;
323	        int16_t *dst;
324	        long long sum2 = 0;
325	        int i;
326	        int c;
327	
328	        if (abort != NULL && *abort) {
329	            result = AI_REC_ABORTED;
330	            break;
331	        }
332	        if (pcm_len + (size_t)chunk_frames * out_frame_bytes > cap) {
333	            result = AI_REC_OK;     /* 到达时长上限，按正常结束处理 */
334	            break;
335	        }
336	
337	        /* 读一块多声道数据到暂存区 */
338	        rc = pcm_read(handle, (const char *)scratch, chunk_frames,
339	                      in_frame_bytes);
340	        if (rc <= 0) {
341	            printf("[Audio] 读取失败: %d\n", rc);
342	            result = AI_REC_ERROR;
343	            break;
344	        }
345	
346	        /* 下混成单声道并施加数字增益。
347	         * DMIC 驱动没有暴露增益控件，实测录音偏小，只能在这里补。
348	         * 取平均而非取单路：不确定麦克风落在那一路，取平均对两种情况都成立。 */
349	        src = scratch;
350	        dst = (int16_t *)(buf + 44 + pcm_len);
351	        for (i = 0; i < rc; i++) {
352	            int32_t acc = 0;
353	            int32_t v;
354	
355	            for (c = 0; c < (int)in_ch; c++) {
356	                acc += src[i * (int)in_ch + c];
357	            }
358	            acc /= (int32_t)in_ch;
359	
360	            v = acc * (int32_t)gain;
361	            if (v > 32767) {
362	                v = 32767;
363	            } else if (v < -32768) {
364	                v = -32768;
365	            }
366	
367	            dst[i] = (int16_t)v;
368	            sum2 += (long long)v * v;
369	        }
370	        pcm_len += (size_t)rc * out_frame_bytes;
371	
372	        /* 静音判定：均方与门限平方比，等价于"RMS 是否超过门限"，
373	         * 但省掉了每块的平方根 */
374	        if (sum2 > (long long)thr * thr * rc) {
375	            silence_run = 0;
376	            speech_chunks++;
377	            sec_speech++;
378	        } else {
379	            silence_run++;
380	        }
381	        chunks++;
382	
383	        /* 累计本秒的统计量。
384	         * 注意量的是**施加增益之后**的波形，所以调过 MIC_GAIN 之后
385	         * 门限要跟着同比例改（增益翻倍 -> RMS 翻倍 -> 门限也要翻倍）。 */
386	        {
387	            unsigned int chunk_rms =
388	                isqrt_u32((uint32_t)(rc > 0 ? (long long)(sum2 / rc) : 0));
389	
390	            sec_sum2 += sum2;
391	            sec_n += rc;
392	            if (sec_chunks == 0 || chunk_rms < sec_min) {
393	                sec_min = chunk_rms;
394	            }
395	            if (chunk_rms > sec_max) {
396	                sec_max = chunk_rms;
397	            }
398	            sec_chunks++;
399	        }
400	
401	        /* 每满 1 秒打一行，数值可与上面打印的门限直接对照。
402	         *
403	         * 这里的整秒 RMS 是这一秒**全部采样点**的平均。原来打的是"这一秒
404	         * 最后一块"的瞬时值，于是出现过 "RMS≈212 但人声占比 60%" 这种
405	         * 自相矛盾的行 —— 累计占比配瞬时 RMS，两个口径对不上。
406	         * 人声占比同理改成**本秒**的，含义才和同一行里的 RMS 一致。 */
407	        if (sec_chunks >= (int)(1000 / AI_CHUNK_MS)) {
408	            unsigned int sec_rms =
409	                isqrt_u32((uint32_t)(sec_n > 0 ? sec_sum2 / sec_n : 0));
410	
411	            printf("[Audio] %d 秒, RMS 平均 %u [最低 %u, 最高 %u] (门限 %u), "
412	                   "本秒人声 %d%%\n",
413	                   ++sec_no, sec_rms, sec_min, sec_max, thr,
414	                   sec_speech * 100 / sec_chunks);
415	
416	            sec_sum2 = 0;
417	            sec_n = 0;
418	            sec_min = 0;
419	            sec_max = 0;
420	            sec_chunks = 0;
421	            sec_speech = 0;
422	        }
423	
424	        if (speech_chunks == 0 && chunks >= AI_NOSPEECH_CHUNKS) {
425	            result = AI_REC_NOSPEECH;
426	            break;
427	        }
428	        /* 收尾条件，两条取或：
429	         *
430	         * 正常路径 —— 说过话（累计 >=300ms）之后连续静音 2 秒。
431	         *
432	         * 兜底路径 —— speech_chunks 是**累计**值，说一句很短的"喂喂"只产生
433	         * 2 块超门限的音频，永远够不到 AI_MIN_SPEECH_CHUNKS，上面那条就
434	         * 再也不成立；而 speech_chunks == 0 的无人声兜底也失效了（是 2 不是 0）。
435	         * 实测此情形下紧接着 8 秒静音都没能收尾，一路录到 16.5 秒，只能靠
436	         * 用户再次出声把累计值顶上去。所以只要出过声，静音够长就强制结束。
437	         */
438	        if ((speech_chunks >= AI_MIN_SPEECH_CHUNKS &&
439	             silence_run >= AI_SILENCE_CHUNKS) ||
440	            (speech_chunks > 0 && silence_run >= AI_LONG_SILENCE_CHUNKS)) {
441	            result = AI_REC_OK;
442	            break;
443	        }
444	    }
445	
446	    snd_vela_pcm_drain(handle);
447	    snd_vela_pcm_close(handle);
448	    free(scratch);
449	
450	    if (result != AI_REC_OK) {
451	        printf("[Audio] 录音结束: %s\n", audio_rec_strerror(result));
452	        free(buf);
453	        return result;
454	    }
455	
456	    wav_write_header(buf, (uint32_t)pcm_len, AI_REC_CHANNELS,
457	                     AI_REC_RATE, AI_REC_BITS);
458	    *out = buf;
459	    *out_len = 44 + pcm_len;
460	
461	    printf("[Audio] 录音完成: %.1f 秒, %u 字节\n",
462	           (double)pcm_len / (AI_REC_RATE * out_frame_bytes),
463	           (unsigned)(44 + pcm_len));
464	    return AI_REC_OK;
465	}
466	
467	ai_play_result_t audio_play_wav(const uint8_t *wav, size_t len,
468	                                volatile int *abort)
469	{
470	    snd_pcm_t *handle = NULL;
471	    unsigned rate = 0, channels = 0, bits = 0;
472	    size_t off = 0, data_len = 0;
473	    unsigned frame_bytes;
474	    size_t chunk_bytes;
475	    size_t pos;
476	    ai_play_result_t result = AI_PLAY_OK;
477	    int rc;
478	
479	    if (wav_parse(wav, len, &rate, &channels, &bits, &off, &data_len) != 0) {
480	        printf("[Audio] 音频格式不支持（需要 16bit PCM WAV）\n");
481	        return AI_PLAY_ERROR;
482	    }
483	
484	    frame_bytes = channels * (bits / 8);
485	
486	    rc = snd_vela_pcm_open(&handle, AI_PCM_DEVICE,
487	                           SND_VELA_PCM_STREAM_PLAYBACK, 0);
488	    if (rc < 0) {
489	        printf("[Audio] 打开播放设备失败: %d\n", rc);
490	        return AI_PLAY_ERROR;
491	    }
492	
493	    /* 云端 TTS 是 24kHz 单声道，这里按头里的实际值配，不重采样 */
494	    rc = set_param(handle, SND_PCM_FORMAT_S16_LE, rate, channels, 1024, 4096);
495	    if (rc < 0) {
496	        printf("[Audio] 播放参数配置失败: %d\n", rc);
497	        snd_vela_pcm_close(handle);
498	        return AI_PLAY_ERROR;
499	    }
500	
501	    printf("[Audio] 开始播放: %u Hz / %u 声道 / %.1f 秒\n",
502	           rate, channels, (double)data_len / (rate * frame_bytes));
503	
504	    chunk_bytes = (rate / (1000 / AI_CHUNK_MS)) * frame_bytes;
505	
506	    for (pos = 0; pos < data_len; ) {
507	        size_t n = data_len - pos;
508	        snd_pcm_uframes_t frames;
509	
510	        if (abort != NULL && *abort) {
511	            result = AI_PLAY_ABORTED;
512	            break;
513	        }
514	        if (n > chunk_bytes) {
515	            n = chunk_bytes;
516	        }
517	
518	        frames = (snd_pcm_uframes_t)(n / frame_bytes);
519	        if (frames == 0) {
520	            break;
521	        }
522	
523	        rc = pcm_write(handle, (char *)(wav + off + pos), frames, frame_bytes);
524	        if (rc <= 0) {
525	            printf("[Audio] 写入失败: %d\n", rc);
526	            result = AI_PLAY_ERROR;
527	            break;
528	        }
529	        pos += (size_t)rc * frame_bytes;
530	    }
531	
532	    snd_vela_pcm_drain(handle);
533	    snd_vela_pcm_close(handle);
534	
535	    printf("[Audio] 播放结束: %s\n", audio_play_strerror(result));
536	    return result;
537	}
