1	/*
2	 * AI模拟面试官 — 编译期配置与运行时覆盖
3	 * 负责：A同学
4	 *
5	 * 这里所有带 CONFIG_ 前缀的宏都有 #ifndef 兜底：Kconfig 项要等 mkkconfig.sh
6	 * 重新扫描目录后才会进 .config，本地工作区若尚未构建过，宏不存在会导致编译失败。
7	 */
8	
9	#ifndef __APP_CONFIG_H__
10	#define __APP_CONFIG_H__
11	
12	#include <stdlib.h>
13	#include <string.h>
14	
15	/* ---- 云端服务地址（不含路径）----
16	 * 默认值填的是**演示环境的实际地址**，不是占位符。
17	 *
18	 * 原先这里是 "http://192.168.1.100:5000"（占位用）。当时观察到应用报
19	 * "Couldn't connect to server" 且抓包看不到任何包，据此判定"运行期
20	 * `nsh> set CLOUD_URL` 覆盖不生效"，于是把地址直接编了进来。
21	 *
22	 * 事后查明那个结论是**错的**：真正的原因是板子的 wlan0 掉出了热点，
23	 * 根本没在发包 —— 跟 URL 从哪儿来无关。代码路径本身是通的：
24	 * apps/builtin/exec_builtin.c 虽然给 posix_spawn 传 envp = NULL，但
25	 * nuttx/sched/task/task_spawn.c:226 会退化成 environ，内置应用确实继承
26	 * NSH 的环境变量。
27	 *
28	 * 但要注意：运行期覆盖至今**没有在真机上正面验证过**。所以默认值仍然填
29	 * 实际地址，保证不 set 任何东西也能直接跑通。想验证覆盖是否生效，可以故意
30	 * 设一个错的端口，看应用打印的是不是那个错端口：
31	 *   nsh> set CLOUD_URL http://172.20.10.2:9999
32	 *
33	 * 172.20.10.2 是 Windows 宿主机在手机热点上的地址，VMware NAT 把它的
34	 * 5000 端口转发到虚拟机的 Flask。演示环境固定，故直接编进来。
35	 */
36	#ifndef CONFIG_APP_AI_INTERVIEW_CLOUD_URL
37	#  define CONFIG_APP_AI_INTERVIEW_CLOUD_URL "http://172.20.10.2:5000"
38	#endif
39	
40	/* ---- 面试官角色 ----
41	 *
42	 * 取值必须和云端题库的 role 对得上（见 cloud/question_bank.py 的 ROLE_ALIASES），
43	 * 对不上时云端不会报错，只会拿不到参考题、静默退化成自由提问。
44	 *
45	 * ⚠️ 这里带空格，所以**不能**用 `nsh> set ROLE AI 应用开发` 在运行期覆盖 ——
46	 * NSH 的 set 按空白分词，最终只会拿到 `AI`。
47	 */
48	#ifndef CONFIG_APP_AI_INTERVIEW_ROLE
49	#  define CONFIG_APP_AI_INTERVIEW_ROLE "AI 应用开发"
50	#endif
51	
52	/* ---- 单轮录音上限（秒）---- */
53	#ifndef CONFIG_APP_AI_INTERVIEW_MAX_RECORD_SECONDS
54	#  define CONFIG_APP_AI_INTERVIEW_MAX_RECORD_SECONDS 30
55	#endif
56	
57	/* ---- 静音判定阈值（16bit 满幅 32767 的 RMS 门限）----
58	 * 500 是 9/13 定的，9/14 晚按现场底噪上调到 900 —— 依据见
59	 * documents/progress_audit_2026-09-11.md §11.19。
60	 */
61	#ifndef CONFIG_APP_AI_INTERVIEW_SILENCE_THRESHOLD
62	#  define CONFIG_APP_AI_INTERVIEW_SILENCE_THRESHOLD 900
63	#endif
64	
65	/* ---- 采集 PCM 设备名 ----
66	 * 实测确认：这块板子的麦克风接在**数字麦（DMIC）**上，走 hw:snddmic。
67	 * "default" 解析到模拟 codec（audiocodec），那条通路上没有麦克风，
68	 * 采回来的是恒定的全零。
69	 *
70	 * 仍支持运行期覆盖，便于换板子时验证：
71	 *   nsh> set PCM_DEV hw:snddmic
72	 */
73	#ifndef CONFIG_APP_AI_INTERVIEW_CAPTURE_DEV
74	#  define CONFIG_APP_AI_INTERVIEW_CAPTURE_DEV "hw:snddmic"
75	#endif
