77	/* ---- 采集声道数 ----
78	 * DMIC 以 2 声道采集（实测可用）。录音时会下混成单声道再送 ASR。
79	 */
80	#ifndef CONFIG_APP_AI_INTERVIEW_CAPTURE_CHANNELS
81	#  define CONFIG_APP_AI_INTERVIEW_CAPTURE_CHANNELS 2
82	#endif
