84	/* ---- 麦克风数字增益（软件）----
85	 * DMIC 驱动没有暴露增益控件，实测录音偏小，所以在下混时做数字放大。
86	 * 运行期可调，省得为试一个数值重烧：
87	 *   nsh> set MIC_GAIN 8
88	 */
89	#ifndef CONFIG_APP_AI_INTERVIEW_MIC_GAIN
90	#  define CONFIG_APP_AI_INTERVIEW_MIC_GAIN 4
91	#endif
92	
93	static inline const char *app_capture_device(void)
94	{
95	    const char *env = getenv("PCM_DEV");
96	
97	    if (env != NULL && env[0] != '\0') {
98	        return env;
99	    }
100	
101	    return CONFIG_APP_AI_INTERVIEW_CAPTURE_DEV;
102	}
103	
104	static inline unsigned int app_capture_channels(void)
105	{
106	    const char *env = getenv("PCM_CH");
107	    int v;
108	
109	    if (env != NULL && env[0] != '\0') {
110	        v = atoi(env);
111	        if (v >= 1 && v <= 8) {
112	            return (unsigned int)v;
113	        }
114	    }
115	
116	    return CONFIG_APP_AI_INTERVIEW_CAPTURE_CHANNELS;
117	}
118	
119	static inline unsigned int app_mic_gain(void)
120	{
121	    const char *env = getenv("MIC_GAIN");
122	    int v;
123	
124	    if (env != NULL && env[0] != '\0') {
125	        v = atoi(env);
126	        if (v >= 1 && v <= 64) {
127	            return (unsigned int)v;
128	        }
129	    }
130	
131	    return CONFIG_APP_AI_INTERVIEW_MIC_GAIN;
132	}
133	
134	/*
135	 * 下面三个原本是编译期常量，改成运行期可覆盖 —— 理由是它们都属于
136	 * "必须对着现场实测值反复试"的参数，而重烧一次的成本远高于输入一条命令：
137	 *
138	 *   nsh> set SILENCE_THRESHOLD 800   # 静音门限（RMS，16bit 满幅）
139	 *   nsh> set MAX_REC_SEC 15          # 单轮录音上限（秒）
140	 *   nsh> set ROLE 技术总监            # 面试官角色
141	 */
142	
143	/* ---- 静音判定阈值（16bit 满幅 32767 的 RMS 门限）----
144	 * 调法：先在日志里看实测 RMS —— 说话时取一个偏低的稳定值，安静时取偏高的，
145	 * 门限放在两者中间。开太低会把环境噪声当人声（永远不停），开太高会把
146	 * 说话当静音（录不满就截断）。
147	 *
148	 * 注意这不是"绝对灵敏度"，而是**当前房间底噪 + 这块板子自噪**的匹配值：
149	 * 同一个固件换个房间就该重调。判据是日志里静音段那几行的"RMS 平均"，
150	 * 它越过门限就意味着程序把安静当成了说话。
151	 */
152	static inline unsigned int app_silence_threshold(void)
153	{
154	    const char *env = getenv("SILENCE_THRESHOLD");
155	    int v;
156	
157	    if (env != NULL && env[0] != '\0') {
158	        v = atoi(env);
159	        if (v >= 1 && v <= 32767) {
160	            return (unsigned int)v;
161	        }
162	    }
163	
164	    return CONFIG_APP_AI_INTERVIEW_SILENCE_THRESHOLD;
165	}
166	
167	static inline unsigned int app_max_record_seconds(void)
168	{
169	    const char *env = getenv("MAX_REC_SEC");
170	    int v;
171	
172	    if (env != NULL && env[0] != '\0') {
173	        v = atoi(env);
174	        if (v >= 1 && v <= 300) {
175	            return (unsigned int)v;
176	        }
177	    }
178	
179	    return CONFIG_APP_AI_INTERVIEW_MAX_RECORD_SECONDS;
180	}
181	
182	/* 面试官角色。演示时换个岗位只需 set ROLE，不必重烧。 */
183	static inline const char *app_role(void)
184	{
185	    const char *env = getenv("ROLE");
186	
187	    if (env != NULL && env[0] != '\0') {
188	        return env;
189	    }
190	
191	    return CONFIG_APP_AI_INTERVIEW_ROLE;
192	}
193	
194	/* ---- 流水线工作线程栈大小 ----
195	 * 必须够大：libcurl 在这个 port 上要 200KB 量级
196	 * （参考 CONFIG_EXAMPLES_HTTP_STACKSIZE 默认 204800），而
197	 * CONFIG_PTHREAD_STACK_DEFAULT 只有 4096。
198	 */
199	#ifndef CONFIG_APP_AI_INTERVIEW_WORKER_STACKSIZE
200	#  define CONFIG_APP_AI_INTERVIEW_WORKER_STACKSIZE 262144
201	#endif
202	
203	/* 判断是不是一个可用的完整 URL（http 或 https，且协议后有内容）*/
204	static inline int app_url_is_valid(const char *u)
205	{
206	    const char *rest;
207	
208	    if (u == NULL) {
209	        return 0;
210	    }
211	
212	    if (strncmp(u, "https://", 8) == 0) {
213	        rest = u + 8;
214	    } else if (strncmp(u, "http://", 7) == 0) {
215	        rest = u + 7;
216	    } else {
217	        return 0;
218	    }
219	
220	    return rest[0] != '\0';
221	}
222	
223	/*
224	 * 取云端 base 地址。
225	 * 环境变量 CLOUD_URL 优先于 Kconfig：演示当天换服务器只需
226	 *   nsh> set CLOUD_URL http://192.168.1.23:5000
227	 * 不必重新编译烧录（内置应用会继承 NSH 的环境变量）。
228	 *
229	 * 同样接受 https:// —— 走内网穿透或公网部署时给的就是 https 地址。
230	 * 端侧能跑 TLS：CONFIG_LIB_CURL 会带入 mbedtls。
