"""结构化评分的"闸"：把模型吐回来的 JSON 收拾成可信的形状。

为什么需要它
------------
报告目前只有一段 200 字的文本（`skills/generate_feedback.json` 里 `max_tokens`
是 600，200 字是团队锁定的上限，不能靠加长文本来塞分项）。想看"哪一项弱、
弱在哪句话上"，就得让模型额外给一份结构化评分。

但**模型给出的分数不能直接信**：

* 它会写 `json` 之外的解释文字、包 ``` 围栏、加 `以下是我的评分：` 前缀；
* 它会把某个维度打成 12 分（满分 10）、"良好"（不是数字）、漏掉一个维度；
* 它算不对算术 —— 所以**总分由我们算**，永远不采信模型自己算的 total。

这个模块的职责就是把上面这些全部挡掉：`extract_json` 负责"从一坨文本里挖出
那个 JSON"，`normalize` 负责"把残缺/越界的字段收拾干净或丢弃"，`is_usable`
负责"这份评分到底能不能用"。全部是纯函数，可单测（同 `reply_guard` 的纪律）。

维度是**代码里定死的**（`DIMENSIONS`）
--------------------------------------
单人自练的场景下，固定维度才有意义 —— 不固定就没法纵向比较"上个月这项 6 分，
这个月 7 分"。这个元组是唯一事实来源：P2 的提示词由它生成，`normalize` 也用它
校验，因此不存在"提示词里写了 5 个维度、代码只认 4 个"这种漂移。
"""
import json
import re

# 评分维度：唯一事实来源。改这里就等于改提示词（P2 会把它拼进 prompt）。
DIMENSIONS = ("表达与逻辑", "专业深度", "项目经验", "岗位匹配")

# 单维度满分。用 0~10 的整数：模型对 10 分制最稳，而且前端画条形图够用。
MAX_SCORE = 10

# 各字段的长度上限 —— 这是**语音**产品，评分是给人看的短评，不是小作文。
EVIDENCE_MAX = 60
COMMENT_MAX = 80
SUMMARY_MAX = 160

_FENCE_RE = re.compile(r"```[a-zA-Z]*\s*(.*?)```", re.DOTALL)

# 与 finish_guard._PUNCT_RE 同一套字符集（刻意不跨模块 import：两个 guard
# 各自独立可读、可单测，比省下这一行更重要）。
_PUNCT_RE = re.compile(
    r"[\s　。，、！？!?,;；:：…~～·\"'“”‘’（）()\[\]【】《》<>-]+"
)


def extract_json(text):
    """从模型输出里挖出第一个 JSON 对象；挖不到返回 None。

    依次尝试：``` 围栏里的内容 → 整段文本。取对象用**花括号配对**而不是
    `rfind("}")`：模型常在 JSON 后面再补一句"希望对您有帮助"，`rfind` 会把
    那句话里的 `}`（如果有）连进来，配对计数不会。
    """
    if not text:
        return None

    candidates = []
    fenced = _FENCE_RE.search(text)
    if fenced:
        candidates.append(fenced.group(1))
    candidates.append(text)

    for candidate in candidates:
        blob = _first_object(candidate)
        if not blob:
            continue
        try:
            data = json.loads(blob)
        except ValueError:
            continue
        if isinstance(data, dict):
            return data
    return None


def _first_object(text: str) -> str:
    """返回第一个花括号配对完整的子串；找不到返回 `""`。

    计数时要跳过字符串**内部**的括号（`{"comment": "他写了 {" }` 这种），
    否则会提前截断。
    """
    start = text.find("{")
    if start < 0:
        return ""

    depth = 0
    in_string = False
    escaped = False
    for i in range(start, len(text)):
        ch = text[i]
        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_string = False
            continue
        if ch == '"':
            in_string = True
        elif ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                return text[start:i + 1]
    return ""


def _clean_str(value, limit: int) -> str:
    """取出一个可展示的短字符串：非字符串当空，压掉换行，超长截断。"""
    if not isinstance(value, str):
        return ""
    text = re.sub(r"\s+", " ", value).strip()
    if len(text) > limit:
        text = text[:limit].rstrip() + "…"
    return text


def _as_score(value):
    """把模型给的分数收拾成 0~MAX_SCORE 的整数；给不出数字则返回 None。

    接受数字字符串（模型有时会写成 `"7"`），拒绝布尔值（`True` 在 Python 里
    是 int 的子类，不特判就会变成 1 分）。
    """
    if isinstance(value, bool) or value is None:
        return None
    if isinstance(value, str):
        try:
            value = float(value.strip().rstrip("分"))
        except ValueError:
            return None
    if not isinstance(value, (int, float)):
        return None
    # 越界一律夹到边界，而不是丢弃 —— 模型打成 12 分说明它认为"很好"，
    # 丢掉这一维反而会让评分缺一块。
    return int(max(0, min(MAX_SCORE, round(value))))


def normalize(raw):
    """把模型给的原始结构收拾成规范评分；无法收拾时返回 `{}`。

    规范形状：

        {"dimensions": [{"name", "score", "max", "evidence", "comment"}, ...],
         "missing":    ["岗位匹配", ...],     # 模型漏掉的维度，如实记录
         "total":      75,                    # 0~100，**我们算的**
         "summary":    "一句话总评",
         "status":     "ok"}

    刻意**丢掉**模型自己算的 total：它算不对，而总分是给人看的第一眼数字，
    错一位就会被当成评分不可信。缺失的维度也不补零 —— 补零等于凭空扣分，
    如实列在 `missing` 里让前端显示"未评"才是诚实的。
    """
    if not isinstance(raw, dict):
        return {}

    items = raw.get("dimensions")
    if not isinstance(items, list):
        return {}

    dims = []
    seen = set()
    for item in items:
        if not isinstance(item, dict):
            continue
        name = _clean_str(item.get("name"), 16)
        if name not in DIMENSIONS or name in seen:
            continue          # 不认识的维度直接丢，不让它污染固定的四维
        score = _as_score(item.get("score"))
        if score is None:
            continue
        seen.add(name)
        dims.append({
            "name": name,
            "score": score,
            "max": MAX_SCORE,
            "evidence": _clean_str(item.get("evidence"), EVIDENCE_MAX),
            "comment": _clean_str(item.get("comment"), COMMENT_MAX),
        })

    if not dims:
        return {}

    # 固定顺序：前端表格与纵向对比都依赖它，不能随模型输出的顺序飘。
    dims.sort(key=lambda d: DIMENSIONS.index(d["name"]))

    return {
        "dimensions": dims,
        "missing": [d for d in DIMENSIONS if d not in seen],
        "total": round(sum(d["score"] for d in dims) / len(dims) * 10),
        "summary": _clean_str(raw.get("summary"), SUMMARY_MAX),
        "status": "ok",
    }


def is_usable(score) -> bool:
    """这份评分能不能展示给用户（结构完整、分数都在合法区间内）。"""
    if not isinstance(score, dict):
        return False
    dims = score.get("dimensions")
    if not isinstance(dims, list) or not dims:
        return False
    for dim in dims:
        if not isinstance(dim, dict):
            return False
        value = dim.get("score")
        if not isinstance(value, int) or isinstance(value, bool):
            return False
        if not 0 <= value <= MAX_SCORE:
            return False
    return isinstance(score.get("total"), int)


def evidence_supported(quote, history) -> bool:
    """这句"证据"是不是真的出自候选人的原话。

    用途是**核对**而不是拦截：模型经常把原话压缩或改一两个字（"我负责检索模块"
    → "负责检索模块"），严格判定会大面积误报。所以这里只回答"能不能在候选人的
    发言里找到"，由调用方决定是记日志还是打标记，不用它否掉整份评分。

    比对前把标点和空白全部压掉 —— 语音转写出来的标点本来就不可信。
    """
    target = _squash(quote)
    if not target:
        return False
    for message in history or []:
        if not isinstance(message, dict) or message.get("role") != "user":
            continue
        if target in _squash(message.get("content", "")):
            return True
    return False


def verify_evidence(score, history) -> list:
    """逐维度核对证据，返回**没能对上原话**的维度名列表（对上则为空列表）。"""
    bad = []
    for dim in (score or {}).get("dimensions", []) or []:
        if not isinstance(dim, dict):
            continue
        if not evidence_supported(dim.get("evidence", ""), history):
            bad.append(dim.get("name", "?"))
    return bad


def _squash(text) -> str:
    """压掉空白与标点，用于"这句原话在不在历史里"的子串比对。"""
    if not text:
        return ""
    return _PUNCT_RE.sub("", str(text)).lower()

"""把一场面试渲染成可下载的文件（Markdown / JSON）。

为什么需要它
------------
报告此前只存在于网页上（`cloud/static/index.html`）。网页适合当场看，不适合
"存下来过几个月再对比" —— 而单人自练最有价值的用法恰恰是回头看。所以给一个
**下载**出口：Markdown 给人读、也能直接贴进笔记软件，JSON 给以后做纵向分析用。

输入就是 `session_manager.snapshot()` 的那份字典（落盘存的也是它，见
`session_store.py`），因此"内存里、磁盘上、导出的文件"三者的字段永远一致。

两个刻意的选择
--------------
* **文件名用 ASCII**。`Content-Disposition` 里的非 ASCII 文件名要走 RFC 5987
  编码，Werkzeug 的 `send_file(download_name=...)` 版本间行为不完全一致。中文
  标题写在**文件正文**里，文件名只用会话 id 和时间 —— 少一个能出岔子的地方。
* **报告正文复用已有内容**，不另存一份。报告就是最后那条 assistant 消息
  （`llm_service.generate_feedback` 的产物），落盘时也不再复制一遍
  （见 `report_text` 的取值顺序）。
"""
import json
import re
import time

SUPPORTED = ("md", "json")

MIME = {"md": "text/markdown; charset=utf-8", "json": "application/json; charset=utf-8"}


def report_text(snapshot) -> str:
    """取这场面试的报告正文。

    取值顺序（P1 起）：优先用快照里的 `report` 字段；没有就看它是不是已结束，
    是的话取最后一条 assistant 消息 —— 报告本来就是模型那轮的输出，**不另存一份**
    （存两份就会有两份不一致的那一天）。
    """
    if not isinstance(snapshot, dict):
        return ""
    report = snapshot.get("report")
    if isinstance(report, str) and report.strip():
        return report.strip()
    if snapshot.get("is_finished"):
        for message in reversed(snapshot.get("messages") or []):
            if message.get("role") == "assistant" and message.get("content"):
                return str(message["content"]).strip()
    return ""


def _fmt_time(value) -> str:
    """时间戳转本地时间字符串；给不出就返回空串（不抛异常）。"""
    try:
        return time.strftime("%Y-%m-%d %H:%M", time.localtime(float(value)))
    except (TypeError, ValueError, OSError, OverflowError):
        return ""


def _session_name(snapshot) -> str:
    """文件名用的会话短标识：只保留 id 的 ASCII 安全字符。"""
    raw = str((snapshot or {}).get("session_id", "") or "")
    safe = re.sub(r"[^A-Za-z0-9_-]", "", raw)[:8]
    return safe or "session"


def filename(snapshot, fmt: str = "md") -> str:
    """下载文件名：`interview_report_<id8>_<YYYYmmdd-HHMM>.md`。"""
    stamp = time.strftime("%Y%m%d-%H%M", time.localtime())
    return f"interview_report_{_session_name(snapshot)}_{stamp}.{fmt}"


def to_markdown(snapshot) -> str:
    """渲染 Markdown 报告：抬头 → 总评 → 评分 → 对话记录。"""
    snapshot = snapshot or {}
    lines = ["# AI 模拟面试官 · 面试报告", ""]

    role = snapshot.get("role") or "（未知岗位）"
    lines.append(f"- **岗位**：{role}")
    if snapshot.get("session_id"):
        lines.append(f"- **会话**：{snapshot['session_id']}")
    started = _fmt_time(snapshot.get("created_at"))
    if started:
        lines.append(f"- **开始**：{started}")
    ended = _fmt_time(snapshot.get("updated_at"))
    if ended:
        lines.append(f"- **最后更新**：{ended}")
    if snapshot.get("question_count") is not None:
        lines.append(f"- **问答轮次**：{snapshot.get('question_count', 0)}")
    lines.append(f"- **状态**：{'已结束' if snapshot.get('is_finished') else '进行中'}")
    lines.append("")

    text = report_text(snapshot)
    lines += ["## 总评", "", text or "（本次面试还没有生成报告）", ""]

    score = snapshot.get("score")
    dimensions = (score or {}).get("dimensions") if isinstance(score, dict) else None
    if dimensions:
        lines += ["## 评分", ""]
        if isinstance(score.get("total"), int):
            lines.append(f"**总分：{score['total']} / 100**")
            lines.append("")
        lines += ["| 维度 | 得分 | 评语 |", "| --- | --- | --- |"]
        for dim in dimensions:
            score_text = f"{dim.get('score', '?')} / {dim.get('max', 10)}"
            comment = str(dim.get("comment") or "—").replace("|", "\\|")
            lines.append(f"| {dim.get('name', '?')} | {score_text} | {comment} |")
        lines.append("")
        for dim in dimensions:
            if dim.get("evidence"):
                lines.append(f"> **{dim.get('name', '')}** 依据：{dim['evidence']}")
        lines.append("")
        missing = score.get("missing") or []
        if missing:
            lines.append(f"（本次未评的维度：{'、'.join(missing)}）")
            lines.append("")
        if score.get("summary"):
            lines += [f"**一句话总评**：{score['summary']}", ""]

    messages = snapshot.get("messages") or []
    lines += ["## 对话记录", ""]
    if not messages:
        lines.append("（没有对话内容）")
        lines.append("")
    for message in messages:
        speaker = "面试官" if message.get("role") == "assistant" else "候选人"
        lines.append(f"**{speaker}**：{message.get('content', '')}")
        lines.append("")

    lines += ["---", "由 AI 模拟面试官生成（openvela 大赛 2026 · 151 号队 mianbao）", ""]
    return "\n".join(lines)


def to_json(snapshot) -> str:
    """整份快照的 JSON（含评分与完整对话），给以后做纵向分析用。"""
    return json.dumps(snapshot or {}, ensure_ascii=False, indent=2)


def export(snapshot, fmt: str = "md"):
    """按格式渲染，返回 `(正文, MIME, 文件名)`；格式不支持时返回 None。

    返回 None 而不是抛异常：路由那边要据此回 400，用异常反而要多写一层 try。
    """
    fmt = (fmt or "md").lower()
    if fmt not in SUPPORTED:
        return None
    body = to_markdown(snapshot) if fmt == "md" else to_json(snapshot)
    return body, MIME[fmt], filename(snapshot, fmt)

#!/usr/bin/env python3
"""finish_guard 单元测试 —— 不联网、不需要 key：`python3 test_finish_guard.py`。

分两类样本，**第二类才是重点**：

* 「该结束的」—— 真实会说的收尾话，包括带礼貌外壳的；
* 「不该结束的」—— 技术回答里合法出现的「结束/没问题/没了」。误判的代价是
  面试被莫名打断，所以这一类的每一条都是按"候选人在回答技术问题"的场景写的，
  不是随手编的反例。
"""
import unittest

from finish_guard import (
    MAX_LEN,
    _FINISH_PHRASES,
    is_finish_request,
    match_reason,
    normalize,
)


class TestWhitelistIsNormalized(unittest.TestCase):
    """白名单里的条目必须**已经是归一化形式** —— 否则是永远匹配不上的死条目。

    这不是假想的风险：初版就把英文写成了 `I'm done`，而 `normalize()` 会把空格
    和撇号全部剥掉（变成 `imdone`），于是那条永远不可能命中 —— 而且没有任何
    测试会失败，功能只是"某天有人说了却没用"。
    """

    def test_every_phrase_is_already_normalized(self):
        for phrase in _FINISH_PHRASES:
            self.assertEqual(normalize(phrase), phrase,
                             f"白名单条目 {phrase!r} 不是归一化形式，永远匹配不上")

    def test_no_phrase_exceeds_length_gate(self):
        """长度闸不能把合法条目挡死：白名单里最长的一条也得 ≤ MAX_LEN。"""
        longest = max(len(p) for p in _FINISH_PHRASES)
        self.assertLessEqual(longest, MAX_LEN,
                             f"最长白名单条目 {longest} 字 > MAX_LEN={MAX_LEN}，该条已失效")

    def test_phrases_are_lowercase(self):
        for phrase in _FINISH_PHRASES:
            self.assertEqual(phrase, phrase.lower(), f"{phrase!r} 含大写字母")


class TestShouldFinish(unittest.TestCase):
    def test_direct(self):
        for text in ("结束", "结束吧", "结束了", "结束面试", "到此为止",
                     "就到这儿吧", "没有别的问题了", "我问完了"):
            with self.subTest(text=text):
                self.assertTrue(is_finish_request(text), f"{text!r} 应当判定为结束")

    def test_with_polite_shell(self):
        """真实收尾话几乎都带礼貌外壳 —— 剥壳是必须的，不是锦上添花。"""
        cases = {
            "好的，我没什么问题了，谢谢老师": "我没什么问题了",
            "嗯，那结束吧": "结束吧",
            "那我们就到这儿吧，谢谢您": "我们就到这儿吧",  # 见下方说明
            "谢谢老师，我没有其他问题了。": "我没有其他问题了",
        }
        for text, expected in cases.items():
            with self.subTest(text=text):
                if expected == "我们就到这儿吧":
                    continue    # 这条需要剥掉"我们"，当前刻意不剥，见下方 test_keeps_we
                self.assertTrue(is_finish_request(text), f"{text!r} 应当判定为结束")

    def test_full_width_and_case(self):
        for text in ("结束吧！", "结束吧。", "That's all.", "I'm done", "STOP"):
            with self.subTest(text=text):
                self.assertTrue(is_finish_request(text), f"{text!r} 应当判定为结束")

    def test_keeps_we_not_supported(self):
        """`那我们就到这儿吧` **不**判定为结束：剥壳只剥语气词，不剥"我们"。

        如实记录这个已知的漏判 —— 它属于"宁可漏判"那一侧：候选人多按一次 K1
        就好，而为了多认出这一句去放宽剥壳规则，会把"我们就到这里吧，这个问题
        先跳过"之类的话也算成结束。要支持它就往白名单加一条精确条目。
        """
        self.assertFalse(is_finish_request("那我们就到这儿吧"))

    def test_match_reason_returns_hit_phrase(self):
        """命中时要能说出命中了哪条 —— 误判排查全靠它。"""
        self.assertEqual(match_reason("结束吧"), "结束吧")
        self.assertEqual(match_reason("我们要结束吧"), "")   # 不精确，不命中


class TestShouldNotFinish(unittest.TestCase):
    """真正重要的那一类：技术回答里的"结束""没问题""没了" **不能**结束面试。"""

    def test_technical_answer_containing_finish_word(self):
        for text in (
            "循环结束的时候会释放资源",
            "这个模块的结束条件我写在析构函数里了",
            "我们在会话结束时把状态落盘",
            "结束时间是晚上六点",
            "我上一份工作结束是因为公司裁员",
        ):
            with self.subTest(text=text):
                self.assertFalse(is_finish_request(text), f"{text!r} 不该判定为结束")

    def test_ambiguous_short_answers(self):
        """含义模糊的一律不判 —— 这几条都能是合法回答，见模块文档。"""
        for text in ("没问题", "可以了", "就这样吧", "没了", "没有了", "行", "好"):
            with self.subTest(text=text):
                self.assertFalse(is_finish_request(text), f"{text!r} 含义模糊，不该判结束")

    def test_question_is_not_a_request(self):
        """带问号的是提问 —— 闸 3。特别是"结束了吗"。"""
        for text in ("结束了吗？", "我们结束了吗？", "结束吧？", "Is it done?"):
            with self.subTest(text=text):
                self.assertFalse(is_finish_request(text), f"{text!r} 是问句，不该判结束")

    def test_negated_or_qualified(self):
        for text in (
            "先别结束，我还想补充一点",
            "我不想结束这个项目",
            "结束之前我想说明一下背景",
            "不好意思我还没说完",
        ):
            with self.subTest(text=text):
                self.assertFalse(is_finish_request(text), f"{text!r} 不该判定为结束")

    def test_long_answer_containing_whitelist_phrase(self):
        """整句精确匹配的意义：含白名单短语的长回答必须落空。"""
        text = "这个流程我认为没有问题了我的意思是它已经跑通了所以可以进入下一阶段"
        self.assertFalse(is_finish_request(text))


class TestGatesAndSafety(unittest.TestCase):
    def test_length_gate_boundary(self):
        """21 字以上一律不看 —— 需要铺垫一长串的都不是"说完了"。"""
        self.assertGreater(MAX_LEN, 0)
        long_text = "结束" + "啊" * (MAX_LEN + 5)
        self.assertFalse(is_finish_request(long_text))

    def test_empty_and_none(self):
        for text in (None, "", "   ", "\n", "，。！"):
            with self.subTest(text=text):
                self.assertFalse(is_finish_request(text))
                self.assertEqual(match_reason(text), "")

    def test_deterministic(self):
        outs = {is_finish_request("好的，我没什么问题了，谢谢老师") for _ in range(20)}
        self.assertEqual(outs, {True})

    def test_normalize_strips_punctuation_and_whitespace(self):
        self.assertEqual(normalize(" 结束 吧 。"), "结束吧")
        self.assertEqual(normalize(None), "")


if __name__ == "__main__":
    unittest.main(verbosity=2)

