#!/usr/bin/env python3
"""score_guard 单元测试 —— 不联网、不需要 key：`python3 test_score_guard.py`。

样本按"模型实际会怎么写"来编：带 ``` 围栏、带前后解释、把分数写成字符串、
打成 12 分、漏掉一个维度、自己算的总分是错的 —— 这些都不是假想，是评分这类
任务里最常见的五种走样。
"""
import unittest

from score_guard import (
    DIMENSIONS,
    MAX_SCORE,
    evidence_supported,
    extract_json,
    is_usable,
    normalize,
    verify_evidence,
