    是为了让日志能说清"它到底匹配上了哪个词"—— 真误判时那是第一手信息。
    """
    if not history:
        return ""
    last = history[-1]
    if not isinstance(last, dict) or last.get("role") != "user":
        return ""
    return match_reason(last.get("content", ""))


