    '<a class="btn" href="/api/export/' + sid + '?format=md">下载 Markdown</a>' +
    '<a class="btn ghost" href="/api/export/' + sid + '?format=json">JSON</a>' +
    '</div>' +
    '<p class="card-note">本场共 ' + rounds + ' 轮问答。报告正文见上方最后一条“面试官”消息。</p>';
  // 评分（P2 才有；没有就不渲染这一段）
  var s = d.score;
  if (s && s.dimensions && s.dimensions.length) {
    html += '<div class="score">';
    if (typeof s.total === "number") {
      html += '<div class="total"><b>' + s.total + '</b><span>/ 100</span></div>';
    }
    html += '<div class="dims">';
    for (var i = 0; i < s.dimensions.length; i++) {
      var dim = s.dimensions[i];
      var pct = Math.max(0, Math.min(100, (dim.score / (dim.max || 10)) * 100));
      html += '<div class="dim"><div class="dim-top"><span>' + esc(dim.name) + '</span>' +
              '<b>' + esc(dim.score) + '</b></div>' +
