    }
    html += '</div>';
    if (s.missing && s.missing.length) {
      html += '<div class="dim-comment">未评：' + esc(s.missing.join("、")) + '</div>';
    }
    if (s.summary) { html += '<div class="summary">' + fmt(s.summary) + '</div>'; }
    html += '</div>';
  }
  html += '</div>';
  return html;
}
