// 面试结束后出现的卡片：结束标识 + 下载入口 +（有的话）结构化评分。
//
// 报告**正文**不在这里重复渲染 —— 它就是最后那条 assistant 消息，已经在
// 上方的气泡里了。复制一份到卡片里迟早会出现"两处不一致"，而且长文本读两遍
// 没有意义。卡片负责的是"这场结束了"这件事，以及拿走的入口。
function reportCard(d) {
  var sid = esc(encodeURIComponent(d.session_id || ""));
  var rounds = (d.messages || []).filter(function (m) { return m.role === "user"; }).length;
  var html =
    '<div class="report-card">' +
      '<div class="card-head">' +
        '<span class="card-title">面试报告</span>' +
        '<span class="spacer"></span>' +
        '<a class="btn" href="/api/export/' + sid + '?format=md">下载 Markdown</a>' +
        '<a class="btn ghost" href="/api/export/' + sid + '?format=json">JSON</a>' +
      '</div>' +
      '<div class="card-note">本场共 ' + rounds +
        ' 轮问答，报告正文见上方最后一条「面试官」消息。</div>';

  var s = d.score;
  if (s && s.dimensions && s.dimensions.length) {
    html += '<div class="score">';
    if (typeof s.total === "number") {
      html += '<div class="total"><b>' + esc(s.total) + '</b>/ 100</div>';
    }
    html += '<div class="dims">';
    for (var i = 0; i < s.dimensions.length; i++) {
      var dim = s.dimensions[i] || {};
      var max = dim.max || 10;
      var pct = Math.max(0, Math.min(100, (dim.score / max) * 100));
      html +=
        '<div class="dim">' +
          '<div class="dim-top"><span>' + esc(dim.name) + '</span>' +
            '<b>' + esc(dim.score) + ' / ' + esc(max) + '</b></div>' +
          '<div class="bar"><i style="width:' + pct + '%"></i></div>' +
          (dim.comment ? '<div class="dim-comment">' + fmt(dim.comment) + '</div>' : "") +
        '</div>';
    }
    html += '</div>';
    if (s.missing && s.missing.length) {
      html += '<div class="dim-comment">本次未评：' + esc(s.missing.join("、")) + '</div>';
    }
    if (s.summary) { html += '<div class="summary">' + fmt(s.summary) + '</div>'; }
    html += '</div>';
  }

  return html + '</div>';
}

// 每次 render 都整块重建（幂等），与消息区的增量追加互不干扰。
function renderReport(d) {
  if (!d.is_finished) {
    elReport.style.display = "none";
    elReport.innerHTML = "";
    elDone.style.display = "none";
    return;
  }
  elDone.style.display = "";
  elReport.innerHTML = reportCard(d);
  elReport.style.display = "";
}

